	    LOGGER.info("handling AssignFilesToCreativeAssetEvent - " );
	    
	    CreativeAsset parentEntity = repository.findById(parentId).get();
	    CreativeFile child = registry.project( CreativeFile.class, addTo.getCreativeFileId());
	    
